SELECT Customers.gender_code, Customers.customer_first_name, Customers.email_address FROM Customers LEFT JOIN Orders ON Customers.customer_id = Orders.customer_id WHERE Orders.order_id IS NULL
SELECT Customers.gender_code, Customers.customer_first_name, Customers.email_address FROM Customers LEFT JOIN Orders ON Customers.customer_id = Orders.customer_id LEFT JOIN Shipments ON Orders.order_id = Shipments.order_id WHERE Shipments.shipment_id IS NULL
SELECT Products.product_id, Customers.gender_code, Products.product_price, Customers.email_address FROM Products JOIN Order_Items ON Products.product_id = Order_Items.product_id JOIN Orders ON Order_Items.order_id = Orders.order_id JOIN Customers ON Orders.customer_id = Customers.customer_id WHERE Order_Items.product_id NOT IN (SELECT Order_Items.product_id FROM Order_Items JOIN Shipments ON Order_Items.order_id = Shipments.order_id GROUP BY Order_Items.product_id HAVING COUNT(Shipments.shipment_id) >= 2)
SELECT Products.product_id, Customers.gender_code, Products.product_price FROM Products JOIN Order_Items ON Products.product_id = Order_Items.product_id JOIN Orders ON Order_Items.order_id = Orders.order_id JOIN Customers ON Orders.customer_id = Customers.customer_id GROUP BY Customers.gender_code ORDER BY COUNT(Products.product_id) DESC
SELECT Products.product_id, Customers.gender_code, Products.product_price FROM Products JOIN Order_Items ON Products.product_id = Order_Items.product_id JOIN Orders ON Order_Items.order_id = Orders.order_id JOIN Customers ON Orders.customer_id = Customers.customer_id GROUP BY Products.product_id, Customers.gender_code ORDER BY COUNT(Products.product_id) DESC
SELECT Products.product_id, SUM(Products.product_price * Customers.gender_code) AS sum FROM Products JOIN Customers ON Products.product_id = Customers.customer_first_name GROUP BY Products.product_id ORDER BY sum ASC LIMIT 1
SELECT Products.product_name, Products.product_price FROM Products JOIN Order_Items ON Products.product_id = Order_Items.product_id JOIN Orders ON Order_Items.order_id = Orders.order_id JOIN Invoices ON Orders.customer_id = Invoices.invoice_number ORDER BY Products.product_price ASC LIMIT 1
SELECT DISTINCT Products.product_name, Products.product_price, Products.product_description FROM Products JOIN Customers ON Products.product_id = Customers.gender_code JOIN Customer_Payment_Methods ON Customers.customer_id = Customer_Payment_Methods.customer_id WHERE Customer_Payment_Methods.payment_method_code LIKE '%female%'
SELECT Products.product_name, Products.product_price, Customers.gender_code FROM Products JOIN Order_Items ON Products.product_id = Order_Items.product_id JOIN Orders ON Order_Items.order_id = Orders.order_id JOIN Customers ON Orders.customer_id = Customers.customer_id WHERE Customers.customer_first_name = 'Female'
SELECT Products.product_price, Customers.customer_first_name FROM Products JOIN Order_Items ON Products.product_id = Order_Items.product_id JOIN Orders ON Order_Items.order_id = Orders.order_id JOIN Customers ON Orders.customer_id = Customers.customer_id WHERE Products.product_price > ( SELECT AVG(product_price) FROM Products )
SELECT Products.product_price, Products.product_size FROM Products JOIN Order_Items ON Products.product_id = Order_Items.product_id JOIN Orders ON Order_Items.order_id = Orders.order_id WHERE Products.product_price > ( SELECT AVG(product_price) FROM Products )
SELECT COUNT(DISTINCT Customers.gender_code) FROM Products JOIN Orders ON Products.product_id = Orders.customer_id JOIN Customers ON Orders.customer_id = Customers.customer_id WHERE Orders.order_status_code IS NULL
SELECT COUNT(Products.product_id) FROM Products LEFT JOIN Order_Items ON Order_Items.product_id = Products.product_id LEFT JOIN Shipment_Items ON Shipment_Items.order_item_id = Order_Items.order_item_id WHERE Shipment_Items.shipment_id IS NULL
SELECT COUNT(Products.product_id) FROM Products LEFT JOIN Orders ON Products.product_id = Orders.customer_id WHERE Orders.order_id IS NULL
SELECT COUNT(Products.product_id) FROM Products LEFT JOIN Orders ON Products.product_id = Orders.customer_id WHERE Orders.order_id IS NULL
SELECT Customers.gender_code, Customers.customer_first_name, Customers.customer_last_name FROM Customers JOIN Orders ON Customers.customer_id = Orders.customer_id JOIN Products ON Products.product_id = Orders.customer_id GROUP BY Customers.gender_code, Customers.customer_first_name, Customers.customer_last_name ORDER BY COUNT(Customers.gender_code) ASC LIMIT 1
SELECT Customers.gender_code, Customers.customer_first_name, Customers.customer_last_name FROM Customers JOIN Orders ON Customers.customer_id = Orders.customer_id JOIN Products ON Products.product_id = Orders.customer_id JOIN Shipments ON Shipments.order_id = Orders.order_id JOIN Invoices ON Invoices.invoice_number = Shipments.invoice_number JOIN Order_Items ON Order_Items.product_id = Products.product_id JOIN Shipment_Items ON Shipment_Items.order_item_id = Order_Items.order_item_id WHERE Customers.email_address = (SELECT email_address FROM Customers JOIN Orders ON Customers.customer_id = Orders.customer_id JOIN Products ON Products.product_id = Orders.customer_id GROUP BY Customers.email_address ORDER BY COUNT(Customers.email_address) ASC LIMIT 1)
SELECT Customers.gender_code, Customers.customer_first_name, Customers.email_address FROM Products JOIN Orders ON Products.product_id = Orders.customer_id JOIN Customers ON Orders.customer_id = Customers.customer_id WHERE Products.product_price < (SELECT MAX(product_price) FROM Products)
SELECT Customers.gender_code, Customers.customer_first_name, Customers.email_address FROM Products JOIN Orders ON Products.product_id = Orders.customer_id JOIN Customers ON Orders.customer_id = Customers.customer_id WHERE Products.product_price < (SELECT MAX(product_price) FROM Products)
SELECT channel.Name FROM channel INNER JOIN director_admin ON channel.Channel_ID = director_admin.Channel_ID GROUP BY channel.Name ORDER BY COUNT(director_admin.Director_ID) DESC LIMIT 1
SELECT channel.Name, director.Age FROM program JOIN director ON program.Director_ID = director.Director_ID JOIN channel ON program.Channel_ID = channel.Channel_ID JOIN director_admin ON director_admin.Channel_ID = channel.Channel_ID GROUP BY channel.Name ORDER BY COUNT(director_admin.Director_ID) DESC LIMIT 1
SELECT COUNT(channel.Name) FROM channel LEFT JOIN program ON channel.Channel_ID = program.Channel_ID LEFT JOIN director_admin ON channel.Channel_ID = director_admin.Channel_ID WHERE program.Director_ID IS NULL AND director_admin.Channel_ID IS NULL
SELECT channel.Name, channel.Digital_terrestrial_channel FROM channel INNER JOIN program ON channel.Channel_ID = program.Channel_ID INNER JOIN director ON program.Director_ID = director.Director_ID GROUP BY channel.Name ORDER BY COUNT(program.Channel_ID) DESC LIMIT 1
SELECT channel.Name FROM channel JOIN program ON channel.Channel_ID = program.Channel_ID JOIN director ON program.Director_ID = director.Director_ID WHERE program.Title LIKE '%Director%' AND director.Age < 40 AND EXISTS (SELECT 1 FROM director AS T2_2 JOIN program AS T3_2 ON T2_2.Director_ID = T3_2.Director_ID WHERE T3_2.Title LIKE '%Director%' AND T2_2.Age > 60 AND T2_2.Director_ID = director.Director_ID)
SELECT driver.Name, driver.Citizenship FROM driver JOIN vehicle_driver ON driver.Driver_ID = vehicle_driver.Driver_ID JOIN vehicle ON vehicle_driver.Vehicle_ID = vehicle.Vehicle_ID WHERE vehicle.Power > 2 OR vehicle.Builder = 'Jeff Gordon'
SELECT driver.Driver_ID, driver.Citizenship FROM driver JOIN vehicle_driver ON driver.Driver_ID = vehicle_driver.Driver_ID JOIN vehicle ON vehicle_driver.Vehicle_ID = vehicle.Vehicle_ID WHERE (SELECT COUNT(*) FROM vehicle_driver AS T4 JOIN vehicle AS T5 ON T4.Vehicle_ID = T5.Vehicle_ID WHERE T5.Model = 'Jeff Gordon') > 1 OR vehicle.Model = 'Jeff Gordon'
SELECT COUNT(*) FROM driver WHERE Driver_ID NOT IN (SELECT Vehicle_ID FROM vehicle_driver)
SELECT COUNT(*) FROM driver WHERE Driver_ID NOT IN (SELECT Vehicle_ID FROM vehicle_driver)
SELECT Customers.address_details FROM Customers INNER JOIN Order_Items ON Customers.customer_id = Order_Items.order_id INNER JOIN Products ON Order_Items.product_id = Products.product_id WHERE Products.product_price > ( SELECT AVG(product_price) FROM Products INNER JOIN Order_Items ON Products.product_id = Order_Items.product_id INNER JOIN Customers ON Order_Items.order_id = Customers.customer_id WHERE Customers.customer_name = 'Hardware' )
SELECT Products.product_type_code FROM Products JOIN Order_Items ON Products.product_id = Order_Items.product_id WHERE Products.product_price > ( SELECT AVG(product_price) FROM Products JOIN Order_Items ON Products.product_id = Order_Items.product_id WHERE Order_Items.order_item_id = 1 )
SELECT Addresses.address_details, Addresses.address_details, Addresses.address_details, Addresses.address_details FROM Addresses JOIN Order_Items ON Order_Items.order_id = Addresses.address_id JOIN Customer_Orders ON Customer_Orders.order_id = Order_Items.order_id JOIN Customers ON Customers.customer_id = Customer_Orders.customer_id JOIN Products ON Products.product_id = Order_Items.product_id ORDER BY Order_Items.product_id DESC LIMIT 1
SELECT Products.product_id, Addresses.address_details, Addresses.address_details AS name, Addresses.address_details AS phone, Addresses.address_details AS email FROM Products JOIN Order_Items ON Products.product_id = Order_Items.product_id JOIN Customer_Orders ON Order_Items.order_id = Customer_Orders.order_id JOIN Customers ON Customer_Orders.customer_id = Customers.customer_id JOIN Addresses ON Customers.address_id = Addresses.address_id ORDER BY Products.product_price DESC LIMIT 1
SELECT COUNT(Products.product_id) FROM Products LEFT JOIN Order_Items ON Products.product_id = Order_Items.product_id WHERE Order_Items.product_id IS NULL
SELECT COUNT(Products.product_id) FROM Products LEFT JOIN Order_Items ON Products.product_id = Order_Items.product_id WHERE Order_Items.order_id IS NULL
SELECT Customer_Orders.order_date, Customer_Orders.order_id FROM Customer_Orders JOIN Order_Items ON Customer_Orders.order_id = Order_Items.order_id JOIN Products ON Order_Items.product_id = Products.product_id WHERE Order_Items.order_quantity > '6' OR Order_Items.order_id IN (SELECT customer_id FROM Customer_Orders GROUP BY customer_id HAVING COUNT(customer_id) > 3)
SELECT Customer_Orders.order_status_code, Customer_Orders.order_date FROM Customer_Orders JOIN Order_Items ON Customer_Orders.order_id = Order_Items.order_id WHERE Order_Items.order_quantity IN (SELECT order_quantity FROM Order_Items WHERE CAST(REPLACE(REPLACE(order_quantity, ',', ''), '$', '') AS REAL) > 6) OR Order_Items.product_id IN (SELECT product_id FROM Products WHERE product_price > 6)
SELECT region.Name FROM building INNER JOIN region ON building.Region_ID = region.Region_ID GROUP BY region.Name ORDER BY COUNT(building.Building_ID) DESC LIMIT 1
SELECT region.Name, region.Capital FROM region JOIN building ON building.Region_ID = region.Region_ID GROUP BY region.Name ORDER BY COUNT(building.Building_ID) DESC LIMIT 1
SELECT Customer_Interactions.Status_Code, Customer_Interactions.Services_and_Channels_Details, COUNT(Analytical_Layer.Analytical_ID) AS total_services FROM Customer_Interactions JOIN Integration_Platform ON Customer_Interactions.Customer_Interaction_ID = Integration_Platform.Customer_Interaction_ID JOIN Analytical_Layer ON Integration_Platform.Integration_Platform_ID = Analytical_Layer.Analytical_ID GROUP BY Customer_Interactions.Status_Code, Customer_Interactions.Services_and_Channels_Details ORDER BY total_services DESC LIMIT 1
SELECT Customer_Interactions.Status_Code, Customer_Interactions.Services_and_Channels_Details, COUNT(Analytical_Layer.Analytical_ID) AS total_services FROM Customer_Interactions JOIN Integration_Platform ON Customer_Interactions.Customer_Interaction_ID = Integration_Platform.Customer_Interaction_ID JOIN Analytical_Layer ON Integration_Platform.Integration_Platform_ID = Analytical_Layer.Analytical_ID GROUP BY Customer_Interactions.Status_Code, Customer_Interactions.Services_and_Channels_Details ORDER BY total_services DESC LIMIT 1
SELECT Customer_Interactions.Status_Code FROM Customer_Interactions INNER JOIN Integration_Platform ON Customer_Interactions.Customer_Interaction_ID = Integration_Platform.Customer_Interaction_ID GROUP BY Customer_Interactions.Status_Code ORDER BY COUNT(Customer_Interactions.Status_Code) DESC LIMIT 1
SELECT Services.Service_Details, COUNT(Customer_Interactions.Customer_Interaction_ID) AS total_services FROM Services JOIN Customers_and_Services ON Services.Service_ID = Customers_and_Services.Service_ID JOIN Customer_Interactions ON Customers_and_Services.Customer_ID = Customer_Interactions.Channel_ID GROUP BY Services.Service_Details ORDER BY total_services DESC LIMIT 1
SELECT Analytical_Layer.Analytical_Layer_Type_Code, Analytical_Layer.Pattern_Recognition, Customer_Interactions.Status_Code, Customer_Interactions.Services_and_Channels_Details, Integration_Platform.Integration_Platform_Details FROM Analytical_Layer INNER JOIN Customers_and_Services ON Analytical_Layer.Customers_and_Services_ID = Customers_and_Services.Customers_and_Services_ID INNER JOIN Customer_Interactions ON Customers_and_Services.Customer_ID = Customer_Interactions.Channel_ID INNER JOIN Integration_Platform ON Customer_Interactions.Customer_Interaction_ID = Integration_Platform.Customer_Interaction_ID INNER JOIN Customers ON Customer_Interactions.Customer_ID = Customers.Customer_ID INNER JOIN Channels ON Customer_Interactions.Channel_ID = Channels.Channel_ID INNER JOIN Services ON Customer_Interactions.Service_ID = Services.Service_ID ORDER BY Customer_Interactions.Status_Code LIMIT 1
SELECT DISTINCT Analytical_Layer.Pattern_Recognition, Analytical_Layer.Analytical_Layer_Type_Code FROM Analytical_Layer JOIN Integration_Platform ON Analytical_Layer.Customers_and_Services_ID = Integration_Platform.Integration_Platform_ID JOIN Customer_Interactions ON Integration_Platform.Customer_Interaction_ID = Customer_Interactions.Customer_Interaction_ID JOIN Customers_and_Services ON Analytical_Layer.Customers_and_Services_ID = Customers_and_Services.Customers_and_Services_ID JOIN Customers ON Customers_and_Services.Customer_ID = Customers.Customer_ID JOIN Services ON Customers_and_Services.Service_ID = Services.Service_ID ORDER BY Analytical_Layer.Analytical_Layer_Type_Code ASC LIMIT 1
SELECT DISTINCT Analytical_Layer.Pattern_Recognition FROM Analytical_Layer INNER JOIN Customers_and_Services ON Analytical_Layer.Customers_and_Services_ID = Customers_and_Services.Customers_and_Services_ID INNER JOIN Customers ON Customers_and_Services.Customer_ID = Customers.Customer_ID WHERE Customers.Customer_Details = 'Hardy Kutch' OR Analytical_Layer.Analytical_Layer_Type_Code = 'good'
SELECT Analytical_Layer.Pattern_Recognition, Analytical_Layer.DESCRIPITIVE_ATTRIBUTE_23 FROM Analytical_Layer INNER JOIN Customers_and_Services ON Analytical_Layer.Customers_and_Services_ID = Customers_and_Services.Customers_and_Services_ID INNER JOIN Customers ON Customers_and_Services.Customer_ID = Customers.Customer_ID INNER JOIN Services ON Customers_and_Services.Service_ID = Services.Service_ID WHERE Services.Service_Details = 'Hardy Kutch' OR Analytical_Layer.DESCRIPITIVE_ATTRIBUTE_23 = 'good'
SELECT DISTINCT Analytical_Layer.Pattern_Recognition FROM Analytical_Layer INNER JOIN Customers_and_Services ON Analytical_Layer.Customers_and_Services_ID = Customers_and_Services.Customers_and_Services_ID INNER JOIN Customers ON Customers_and_Services.Customer_ID = Customers.Customer_ID WHERE Analytical_Layer.Analytical_Layer_Type_Code = 'bad' AND Customers_and_Services.Service_ID = (SELECT Service_ID FROM Services WHERE Service_Details = 'Hardy Kutch')
SELECT Analytical_Layer.Pattern_Recognition, Analytical_Layer.DESCRIPITIVE_ATTRIBUTE_23 FROM Analytical_Layer JOIN Customers_and_Services ON Analytical_Layer.Customers_and_Services_ID = Customers_and_Services.Customers_and_Services_ID JOIN Customers ON Customers_and_Services.Customer_ID = Customers.Customer_ID JOIN Services ON Customers_and_Services.Service_ID = Services.Service_ID WHERE Services.Service_Details = 'Hardy Kutch' AND Analytical_Layer.DESCRIPITIVE_ATTRIBUTE_23 = 'bad'
SELECT Discount.name, Discount.name, Renting_history.total_hours FROM Renting_history JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id JOIN Discount ON Vehicles.id = Discount.id JOIN Customers ON Renting_history.customer_id = Customers.id WHERE Customers.name LIKE '%2013%' OR Customers.name LIKE '%2014%'
SELECT Discount.name, Discount.name, Renting_history.total_hours FROM Renting_history JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id JOIN Discount ON Vehicles.id = Discount.id JOIN Customers ON Renting_history.customer_id = Customers.id WHERE Vehicles.name = 'Model Year' AND Vehicles.Combined_fuel_economy_rate IN (2013, 2014)
SELECT Discount.name, Vehicles.name FROM Renting_history JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id JOIN Discount ON Renting_history.discount_id = Discount.id JOIN Customers ON Renting_history.customer_id = Customers.id GROUP BY Discount.name, Vehicles.name ORDER BY COUNT(Customers.id) DESC LIMIT 1
SELECT Discount.name, Discount.membership_credit FROM Renting_history JOIN Discount ON Renting_history.discount_id = Discount.id JOIN Customers ON Renting_history.customer_id = Customers.id GROUP BY Discount.name, Discount.membership_credit ORDER BY COUNT(Renting_history.id) DESC LIMIT 1
SELECT Discount.name FROM Renting_history INNER JOIN Discount ON Renting_history.discount_id = Discount.id GROUP BY Discount.name ORDER BY COUNT(Renting_history.id) DESC LIMIT 1
SELECT Discount.name FROM Renting_history INNER JOIN Discount ON Renting_history.discount_id = Discount.id GROUP BY Discount.name ORDER BY COUNT(Renting_history.id) DESC LIMIT 1
SELECT Addresses.DESCRIPITIVE_ATTRIBUTE_12, Teachers.teacher_details FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Teachers ON Teachers.teacher_id = Classes.teacher_id JOIN Classes ON Classes.student_id = Students.student_id WHERE Students.student_id IN (SELECT Students.student_id FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id GROUP BY Students.student_id HAVING COUNT(Transcripts.transcript_id) >= 2) OR Students.student_id IN (SELECT Students.student_id FROM Students JOIN Student_Loans ON Students.student_id = Student_Loans.student_id GROUP BY Students.student_id HAVING COUNT(Student_Loans.student_loan_id) < 2)
SELECT Addresses.DESCRIPITIVE_ATTRIBUTE_12, Teachers.teacher_details FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Classes ON Students.student_id = Classes.student_id JOIN Teachers ON Classes.teacher_id = Teachers.teacher_id JOIN Addresses ON Addresses.address_id = Students_Addresses.address_id JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id JOIN Behaviour_Monitoring ON Students.student_id = Behaviour_Monitoring.student_id JOIN Student_Events ON Student_Events.event_type_code = Ref_Event_Types.event_type_code JOIN Student_Loans ON Student_Loans.student_id = Students.student_id JOIN Students AS T4_ ON Addresses.address_id = T4_.address_id WHERE Students_Addresses.date_from IS NOT NULL AND Students_Addresses.date_to IS NOT NULL
SELECT Students.bio_data FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id WHERE Transcripts.transcript_details LIKE '%data%' AND Students.student_id NOT IN (SELECT Students.student_id FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Behaviour_Monitoring ON Students.student_id = Behaviour_Monitoring.student_id WHERE Behaviour_Monitoring.behaviour_monitoring_details LIKE 'net%')
SELECT DISTINCT Students.bio_data FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id WHERE Transcripts.transcript_details LIKE '%data%' AND Students.student_id NOT IN (SELECT Students.student_id FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id WHERE Transcripts.transcript_details LIKE 'net%')
SELECT Student_Loans.amount_of_loan, Student_Loans.date_of_loan FROM Student_Loans JOIN Students ON Student_Loans.student_id = Students.student_id JOIN Classes ON Classes.student_id = Students.student_id WHERE Classes.teacher_id = (SELECT teacher_id FROM Teachers GROUP BY teacher_id HAVING COUNT(teacher_id) >= 2)
SELECT Student_Loans.amount_of_loan, Student_Loans.date_of_loan FROM Student_Loans JOIN Students ON Student_Loans.student_id = Students.student_id JOIN Classes ON Classes.student_id = Students.student_id GROUP BY Student_Loans.student_loan_id HAVING COUNT(Classes.class_id) >= 2
SELECT Students.bio_data, Students.student_id FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id GROUP BY Students.student_id ORDER BY COUNT(Transcripts.transcript_id) DESC LIMIT 1
SELECT Students.bio_data, Students.student_id FROM Students JOIN Behaviour_Monitoring ON Students.student_id = Behaviour_Monitoring.student_id JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Student_Events ON Students.student_id = Student_Events.student_id JOIN Student_Loans ON Students.student_id = Student_Loans.student_id JOIN Classes ON Students.student_id = Classes.student_id JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id JOIN Detention ON Students.student_id = Detention.student_id JOIN Achievements ON Students.student_id = Achievements.student_id GROUP BY Students.student_id ORDER BY COUNT(Students.student_id) DESC LIMIT 1
SELECT Students.bio_data, Students.student_details FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Addresses ON Addresses.address_details = 'most common result' JOIN Students_Addresses ON Students_Addresses.address_id = Addresses.address_id JOIN Ref_Address_Types ON Ref_Address_Types.address_type_description = '3 students in behaviour monitoring' JOIN Students_Addresses AS T13_2 ON T13_2.address_type_code = Ref_Address_Types.address_type_code
SELECT Addresses.address_details, Students.bio_data, Students.student_details FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Addresses ON Addresses.address_id = Students_Addresses.address_id JOIN Students_Addresses ON Students_Addresses.student_id = Students.student_id WHERE Transcripts.date_of_transcript IN ( SELECT date_of_transcript FROM Transcripts GROUP BY date_of_transcript ORDER BY COUNT(date_of_transcript) DESC LIMIT 1 ) AND Transcripts.date_of_transcript IN ( SELECT date_of_transcript FROM Transcripts GROUP BY date_of_transcript HAVING COUNT(date_of_transcript) = 3 )
SELECT Addresses.address_details FROM Addresses JOIN Classes ON Classes.teacher_id = Addresses.address_id JOIN Students ON Students.student_id = Classes.student_id WHERE Classes.class_details IN ( SELECT class_details FROM Classes GROUP BY class_details ORDER BY COUNT(class_id) DESC LIMIT 1 )
SELECT Addresses.address_details FROM Addresses JOIN Classes ON Classes.address_id = Addresses.address_id JOIN Students ON Students.student_id = Classes.student_id JOIN Student_Loans ON Student_Loans.student_id = Students.student_id GROUP BY Addresses.address_details ORDER BY COUNT(Student_Loans.amount_of_loan) DESC LIMIT 1
SELECT COUNT(Students.student_id), Addresses.DESCRIPITIVE_ATTRIBUTE_12, Addresses.DESCRIPITIVE_ATTRIBUTE_12 AS Description FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Addresses ON Transcripts.date_of_transcript = Addresses.DESCRIPITIVE_ATTRIBUTE_12 GROUP BY Addresses.DESCRIPITIVE_ATTRIBUTE_12 ORDER BY COUNT(Students.student_id) DESC LIMIT 1
SELECT Addresses.address_details, COUNT(Students.student_id) AS number_of_students, Addresses.address_details AS event_type_description FROM Students JOIN Classes ON Students.student_id = Classes.student_id JOIN Teachers ON Classes.teacher_id = Teachers.teacher_id JOIN Addresses ON Classes.student_id = Addresses.address_id GROUP BY Addresses.address_details ORDER BY COUNT(Students.student_id) DESC LIMIT 1
SELECT COUNT(Students.student_id) FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Teachers ON Teachers.teacher_id = Classes.teacher_id JOIN Classes ON Classes.student_id = Students.student_id WHERE Teachers.teacher_details = '0'
SELECT COUNT(Students.student_id) FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id WHERE Transcripts.transcript_id NOT IN (SELECT transcript_id FROM Transcripts WHERE transcript_details LIKE '%won%')
SELECT Addresses.address_details, Addresses.address_details FROM Addresses INNER JOIN Students_Addresses ON Addresses.address_id = Students_Addresses.address_id GROUP BY Addresses.address_details ORDER BY COUNT(Addresses.address_details) ASC LIMIT 1
SELECT Addresses.address_details, Ref_Event_Types.event_type_description FROM Addresses JOIN Classes ON Addresses.address_id = Classes.student_id JOIN Teachers ON Classes.teacher_id = Teachers.teacher_id JOIN Ref_Event_Types ON Teachers.teacher_id = Ref_Event_Types.event_type_code GROUP BY Addresses.address_details ORDER BY COUNT(Addresses.address_details) ASC LIMIT 1
SELECT Students.bio_data, Students.student_details, Student_Loans.amount_of_loan, Student_Loans.date_of_loan, Student_Loans.other_details FROM Students JOIN Student_Loans ON Students.student_id = Student_Loans.student_id WHERE Student_Loans.amount_of_loan > (SELECT AVG(amount_of_loan) FROM Student_Loans)
SELECT Students.bio_data, Students.student_details, Addresses.DESCRIPITIVE_ATTRIBUTE_12 FROM Students JOIN Classes ON Students.student_id = Classes.student_id JOIN Teachers ON Classes.teacher_id = Teachers.teacher_id JOIN Student_Loans ON Students.student_id = Student_Loans.student_id WHERE Student_Loans.amount_of_loan > ( SELECT AVG(amount_of_loan) FROM Student_Loans )
SELECT Students.bio_data, Students.student_details FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id WHERE Transcripts.date_of_transcript = (SELECT MIN(date_of_transcript) FROM Transcripts)
SELECT Students.bio_data, Students.student_details FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id JOIN Addresses ON Addresses.address_details = 'earliest transcript issuance' WHERE Transcripts.date_of_transcript = ( SELECT MIN(date_of_transcript) FROM Transcripts )
SELECT Ref_Event_Types.event_type_description, Addresses.address_details FROM Addresses JOIN Classes ON Classes.teacher_id = Addresses.address_id JOIN Teachers ON Teachers.teacher_id = Classes.student_id JOIN Ref_Event_Types ON Ref_Event_Types.event_type_code = Teachers.teacher_details ORDER BY Addresses.address_details DESC LIMIT 1
SELECT Ref_Event_Types.event_type_description, Ref_Event_Types.event_type_description FROM Ref_Event_Types INNER JOIN Student_Events ON Student_Events.event_type_code = Ref_Event_Types.event_type_code GROUP BY Ref_Event_Types.event_type_description ORDER BY COUNT(Ref_Event_Types.event_type_description) DESC LIMIT 1
